import os
import sys
import json
from .secure_api import get_user_models
from .backup_utils import backup_existing_file

# Windows 使用 msvcrt，Unix 使用 tty/termios
if sys.platform == 'win32':
    import msvcrt
    def getch():
        """Windows 下获取单个按键"""
        ch = msvcrt.getch()
        if ch in (b'\x00', b'\xe0'):
            # 方向键前缀
            ch = msvcrt.getch()
            return '\x1b[B'  # 简化为下箭头
        elif ch == b'\r':
            return '\n'
        elif ch == b'\x08':
            return '\x1b[A'  # 退格映射为上箭头
        return ch.decode('utf-8', errors='ignore')
else:
    import tty
    import termios
    def getch():
        """Unix 下获取单个按键，支持方向键"""
        fd = sys.stdin.fileno()
        old_settings = termios.tcgetattr(fd)
        try:
            tty.setraw(fd)
            ch = sys.stdin.read(1)
            if ch == '\x1b':
                ch += sys.stdin.read(2)
        finally:
            termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)
        return ch

AHCLAUDE_DIR = os.path.expanduser("~/.ahdev")
AUTH_CACHE_FILE = os.path.join(AHCLAUDE_DIR, "auth.json")
MODEL_CONFIG_FILE = os.path.join(AHCLAUDE_DIR, "model_config.json")
SETTINGS_FILE = os.path.expanduser("~/.claude/settings.json")


def log_error(msg: str):
    print(f"\n\033[31m[错误] {msg}\033[0m", file=sys.stderr)


def log_warning(msg: str):
    print(f"\n\033[33m[警告] {msg}\033[0m")


def log_success(msg: str):
    print(f"\033[32m{msg}\033[0m")


def load_auth_cache() -> dict:
    if not os.path.exists(AUTH_CACHE_FILE):
        return {}
    try:
        with open(AUTH_CACHE_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}


def load_model_config() -> dict:
    if not os.path.exists(MODEL_CONFIG_FILE):
        return {}
    try:
        with open(MODEL_CONFIG_FILE, "r", encoding="utf-8") as f:
            return json.load(f)
    except (json.JSONDecodeError, IOError):
        return {}


def save_model_config(config: dict):
    try:
        os.makedirs(AHCLAUDE_DIR, exist_ok=True)
        with open(MODEL_CONFIG_FILE, "w", encoding="utf-8") as f:
            json.dump(config, f, ensure_ascii=False, indent=2)
    except IOError as e:
        log_error(f"保存模型配置失败: {e}")
        raise


def load_settings() -> dict:
    if os.path.exists(SETTINGS_FILE):
        try:
            with open(SETTINGS_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except (json.JSONDecodeError, IOError):
            return {}
    return {}


def save_settings(settings: dict):
    try:
        content = json.dumps(settings, ensure_ascii=False, indent=2)
        backup_existing_file(SETTINGS_FILE, "Claude Code settings.json", content)
        with open(SETTINGS_FILE, 'w', encoding='utf-8') as f:
            f.write(content)
    except IOError as e:
        log_error(f"保存 settings.json 失败: {e}")
        raise


def load_user_models(username: str, product: str = None) -> list:
    """获取用户模型列表，支持按平台过滤
    Args:
        username: 用户名
        product: 'claude' 或 'codex'，为空则返回全部
    """
    try:
        return get_user_models(username, product=product)
    except Exception as e:
        log_warning(str(e))
        return []


def update_settings_model(model_id: str):
    settings = load_settings()
    if "env" not in settings:
        settings["env"] = {}

    settings["env"]["ANTHROPIC_MODEL"] = model_id
    settings["env"]["ANTHROPIC_DEFAULT_HAIKU_MODEL"] = model_id
    settings["env"]["ANTHROPIC_DEFAULT_SONNET_MODEL"] = model_id
    settings["env"]["ANTHROPIC_DEFAULT_OPUS_MODEL"] = model_id

    save_settings(settings)


RESET_OPTION_ID = "__reset__"

IMAGE_NO_SUPPORT_WARNING = (
    "\n[警告] 当前选择的模型可能不支持图片输入。\n"
    "       Claude Code 中涉及图片的操作将会失败。\n"
    "       如需使用图片功能，请切换回支持视觉的模型（如 Claude 系列）。\n"
)


_TEXT_ONLY_MODEL_PREFIXES = ("minimax",)


def _model_supports_images(model_id: str, model_data: dict = None) -> bool:
    if model_data:
        modalities = model_data.get("input_modalities")
        if modalities is not None:
            return "image" in modalities
        if "supports_vision" in model_data:
            return bool(model_data["supports_vision"])
    mid = model_id.lower()
    if any(mid.startswith(p) or p in mid for p in _TEXT_ONLY_MODEL_PREFIXES):
        return False
    return True


def run_model_selector_interactive(login_info: dict, reset_label: str = "还原 Claude 默认配置", reset_uninstall_fn=None, update_claude_settings: bool = True, after_select_fn=None, product: str = None):
    """安装流程中的交互式模型选择。
    reset_label: 第一项还原选项的显示文字
    reset_uninstall_fn: 选择还原时调用的卸载函数，None 则用 cmd_uninstall.uninstall
    product: 'claude' 或 'codex'，用于过滤模型列表
    """
    username = login_info.get("username", "")
    # 每次进入都重新拉取最新模型列表，并按平台过滤
    models_data = load_user_models(username, product=product)
    if not models_data:
        log_warning("没有可用模型，跳过模型选择")
        return

    # 这里不再引用本地 app1 包，也不做本地二次过滤。
    # 后端 /api/key-manage/user_models 已经会根据 product 返回对应平台的可见模型列表。

    model_names = login_info.get("model_names", {})

    if not models_data:
        log_warning("没有可用模型，跳过模型选择")
        return

    # 兼容两种格式：字符串列表 ["model_id", ...] 或字典列表 [{"model_id": ..., "model_name": ...}, ...]
    if models_data and isinstance(models_data[0], str):
        normal_models = [(m, model_names.get(m, m)) for m in models_data]
        model_caps = {}
    else:
        normal_models = [(m["model_id"], m.get("model_name", m["model_id"])) for m in models_data]
        model_caps = {m["model_id"]: m for m in models_data}

    models = [(RESET_OPTION_ID, reset_label)]
    models.extend(normal_models)
    current_index = 0

    def draw_menu():
        rows = len(models) + 4
        print(f"\033[{rows}A", end="")
        print("\033[J", end="")
        print(f"当前用户: {username}")
        if models[current_index][0] == RESET_OPTION_ID:
            print(f"当前选项: {reset_label}")
        else:
            print(f"当前模型: {models[current_index][1]}")
        print("请选择模型 (↑↓ 切换, Enter 确认):\n")
        for i, (model_id, model_name) in enumerate(models):
            prefix = "> [●]" if i == current_index else "  [ ]"
            print(f"{prefix} {model_name}")

    draw_menu()

    while True:
        key = getch()
        if key == '\x1b[A':
            current_index = (current_index - 1) % len(models)
            draw_menu()
        elif key == '\x1b[B':
            current_index = (current_index + 1) % len(models)
            draw_menu()
        elif key == '\r' or key == '\n':
            break

    selected_id, selected_name = models[current_index]

    if selected_id == RESET_OPTION_ID:
        print("\n")
        if reset_uninstall_fn:
            reset_uninstall_fn()
        else:
            from .cmd_uninstall import uninstall
            uninstall()
        sys.exit(0)

    config = {
        "username": username,
        "selected_model": selected_id,
        "models": [{"model_id": m[0], "model_name": m[1]} for m in normal_models]
    }
    save_model_config(config)

    if update_claude_settings:
        update_settings_model(selected_id)

    login_info["model"] = selected_id
    if after_select_fn:
        # 关键：选择模型后允许调用方刷新宿主配置，例如 Codex hooks.json 被用户删除/篡改时自动修复。
        after_select_fn(login_info)

    print(f"\n\033[32m已选择模型: {selected_name}\033[0m")
    if not _model_supports_images(selected_id, model_caps.get(selected_id)):
        print(f"\033[33m{IMAGE_NO_SUPPORT_WARNING}\033[0m", end="")


def run_model_selector(login_command: str = "auto++ claude login",
                       reset_label: str = "还原 Claude 默认配置",
                       restart_message: str = "请重启 Claude Code 以加载新模型",
                       reset_uninstall_fn=None,
                       update_claude_settings: bool = True,
                       after_select_fn=None,
                       product: str = None):
    auth = load_auth_cache()
    username = auth.get("username", "")
    if not username:
        print("未检测到登录态，正在启动登录流程...")
        from . import cmd_login
        login_info = cmd_login.ensure_login()
        return run_model_selector_interactive(
            login_info,
            reset_label=reset_label,
            reset_uninstall_fn=reset_uninstall_fn,
            update_claude_settings=update_claude_settings,
            after_select_fn=after_select_fn,
            product=product,
        )

    # 每次选择模型时重新拉取最新列表
    models_data = load_user_models(username, product=product)
    if not models_data:
        log_error("无法获取模型列表")
        sys.exit(1)

    model_config = load_model_config()
    current_model = model_config.get("selected_model", models_data[0]["model_id"])

    model_caps = {m["model_id"]: m for m in models_data}
    models = [(RESET_OPTION_ID, reset_label)]
    models.extend((m["model_id"], m["model_name"]) for m in models_data)

    normal_models_count = len(models) - 1

    if current_model == RESET_OPTION_ID:
        current_index = 1
    else:
        current_index = next((i for i, m in enumerate(models) if m[0] == current_model), 1)

    def draw_menu():
        rows = len(models) + 4
        print(f"\033[{rows}A", end="")
        print("\033[J", end="")
        print(f"当前用户: {username}")
        if models[current_index][0] == RESET_OPTION_ID:
            print(f"当前选项: {reset_label}")
        else:
            print(f"当前模型: {models[current_index][1]}")
        print("请选择模型 (↑↓ 切换, Enter 确认, Q 退出):\n")
        for i, (model_id, model_name) in enumerate(models):
            prefix = "> [●]" if i == current_index else "  [ ]"
            print(f"{prefix} {model_name}")

    draw_menu()

    while True:
        key = getch()
        if key == '\x1b[A':
            current_index = (current_index - 1) % len(models)
            draw_menu()
        elif key == '\x1b[B':
            current_index = (current_index + 1) % len(models)
            draw_menu()
        elif key == '\r' or key == '\n':
            break
        elif key.lower() == 'q':
            print("\n已退出")
            sys.exit(0)

    selected_id, selected_name = models[current_index]

    if selected_id == RESET_OPTION_ID:
        print("\n")
        if reset_uninstall_fn:
            reset_uninstall_fn()
        else:
            from .cmd_uninstall import uninstall
            uninstall()
        sys.exit(0)

    config = {
        "username": username,
        "selected_model": selected_id,
        "models": [{"model_id": m[0], "model_name": m[1]} for m in models[1:]]
    }
    save_model_config(config)

    if update_claude_settings:
        update_settings_model(selected_id)

    if after_select_fn:
        # 关键：模型切换时同步刷新外部配置，避免用户删除 hooks.json 后仍然缺 hook。
        login_info = {
            "username": username,
            "token": auth.get("token", auth.get("api_key", "")),
            "api_key": auth.get("api_key", auth.get("token", "")),
            "model": selected_id,
            "models": [m["model_id"] for m in models_data],
            "model_names": {m["model_id"]: m.get("model_name", m["model_id"]) for m in models_data},
            "model_caps": model_caps,
        }
        after_select_fn(login_info)

    print(f"\n\033[32m已切换到模型: {selected_name}\033[0m")
    if not _model_supports_images(selected_id, model_caps.get(selected_id)):
        print(f"\033[33m{IMAGE_NO_SUPPORT_WARNING}\033[0m", end="")
    print(restart_message)


if __name__ == "__main__":
    run_model_selector()
